@transaction.atomic
def carregar_modelos_completos(apps, schema_editor):
    Modelo = apps.get_model("workspace", "ProjetoCronogramaModelo")
    Etapa = apps.get_model("workspace", "ProjetoCronogramaEtapaModelo")
    Tarefa = apps.get_model("workspace", "ProjetoCronogramaTarefaModelo")
    Subtarefa = apps.get_model("workspace", "ProjetoCronogramaSubtarefaModelo")
    Projeto = apps.get_model("workspace", "Projeto")
    ProjetoEtapa = apps.get_model("workspace", "ProjetoEtapa")
    ProjetoTarefa = apps.get_model("workspace", "ProjetoTarefa")

    legados = {}
    for codigo_base in {dados["tipo_projeto_codigo"] for dados in CRONOGRAMAS.values()}:
        legado = Modelo.objects.filter(codigo=codigo_base).first()
        if legado:
            legado.codigo = f"{codigo_base}-legado-0036"
            legado.ativo = False
            legado.save(update_fields=["codigo", "ativo", "atualizado_em"])
            legados[codigo_base] = legado

    modelos_criados = {}
    for codigo, dados in CRONOGRAMAS.items():
        modelo, _ = Modelo.objects.update_or_create(
            codigo=codigo,
            defaults={
                "tipo_projeto_codigo": dados["tipo_projeto_codigo"],
                "nome": dados["nome"],
                "descricao": dados["descricao"],
                "metodologia": dados["metodologia"],
                "esperada": dados["esperada"],
                "hierarquia": dados["hierarquia"],
                "ativo": True,
                "sistema": True,
            },
        )
        modelos_criados[codigo] = modelo
        ordens_etapas = {etapa["ordem"] for etapa in dados["etapas"]}
        modelo.etapas.exclude(ordem__in=ordens_etapas).delete()
        for etapa_dados in dados["etapas"]:
            ordem_etapa = etapa_dados["ordem"]
            etapa, _ = Etapa.objects.update_or_create(
                modelo=modelo,
                ordem=ordem_etapa,
                defaults={
                    "nome": etapa_dados["nome"],
                    "descricao": etapa_dados["descricao"],
                    "tipo": "sprint" if dados["metodologia"] != "waterfall" else "fase",
                    "offset_inicio_dias_uteis": (ordem_etapa - 1) * 3,
                    "duracao_dias_uteis": 3,
                },
            )
            ordens_tarefas = set(range(1, len(etapa_dados["tarefas"]) + 1))
            etapa.tarefas.exclude(ordem__in=ordens_tarefas).delete()
            for ordem_tarefa, tarefa_dados in enumerate(etapa_dados["tarefas"], start=1):
                tarefa, _ = Tarefa.objects.update_or_create(
                    etapa=etapa,
                    ordem=ordem_tarefa,
                    defaults={
                        "nome": tarefa_dados["nome"],
                        "descricao": "",
                        "tipo": "tarefa",
                        "categoria": "outro",
                        "offset_inicio_dias_uteis": min(ordem_tarefa - 1, 2),
                        "duracao_dias_uteis": tarefa_dados["duracao"],
                        "peso": tarefa_dados["peso"],
                        "obrigatoria": tarefa_dados["obrigatoria"],
                    },
                )
                ordens_subtarefas = {item["ordem"] for item in tarefa_dados["subtarefas"]}
                tarefa.subtarefas.exclude(ordem__in=ordens_subtarefas).delete()
                for subtarefa_dados in tarefa_dados["subtarefas"]:
                    Subtarefa.objects.update_or_create(
                        tarefa=tarefa,
                        ordem=subtarefa_dados["ordem"],
                        defaults={
                            "descricao": subtarefa_dados["descricao"],
                            "obrigatoria": subtarefa_dados["obrigatoria"],
                        },
                    )

    # Todo projeto sem cronograma efetivado inicia na variação Híbrida do seu tipo.
    # Projetos com etapas/tarefas preservam integralmente sua execução; apenas o
    # vínculo de catálogo é alinhado ao modelo Híbrido equivalente.
    for codigo_base, legado in legados.items():
        hibrido = modelos_criados.get(f"{codigo_base}-hibrida")
        if not hibrido:
            continue
        projetos = Projeto.objects.filter(cronograma_modelo=legado)
        for projeto in projetos.iterator():
            tem_execucao = (
                ProjetoEtapa.objects.filter(projeto_id=projeto.pk).exists()
                or ProjetoTarefa.objects.filter(projeto_id=projeto.pk).exists()
            )
            # Execuções efetivadas preservam a metodologia já registrada;
            # rascunhos ainda sem execução voltam ao padrão Híbrido.
            if tem_execucao:
                metodologia_atual = projeto.metodologia if projeto.metodologia in {"agil", "hibrida", "waterfall"} else "hibrida"
                destino = modelos_criados.get(f"{codigo_base}-{metodologia_atual}", hibrido)
                projeto.cronograma_modelo_id = destino.pk
                projeto.save(update_fields=["cronograma_modelo", "atualizado_em"])
            else:
                projeto.cronograma_modelo_id = hibrido.pk
                projeto.metodologia = "hibrida"
                projeto.save(update_fields=["cronograma_modelo", "metodologia", "atualizado_em"])


class Migration(migrations.Migration):
    dependencies = [("workspace", "0036_cronogramas_por_tipo_metodologia")]
    operations = [
        migrations.AddField(
            model_name="projetocronogramamodelo",
            name="tipo_projeto_codigo",
            field=models.SlugField(blank=True, db_index=True, default="", max_length=80),
        ),
        migrations.AddField(
            model_name="projetocronogramamodelo",
            name="esperada",
            field=models.BooleanField(db_index=True, default=False),
        ),
        migrations.AddField(
            model_name="projetocronogramamodelo",
            name="hierarquia",
            field=models.CharField(blank=True, default="", max_length=180),
        ),
        migrations.RunPython(carregar_modelos_completos, migrations.RunPython.noop),
    ]
